--
-- Table structure for table `articles`
--

CREATE TABLE `articles` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `slug` varchar(255) NOT NULL,
  `excerpt` text NOT NULL,
  `content` longtext NOT NULL,
  `featured_image` varchar(255) NOT NULL,
  `image_alt` varchar(255) NOT NULL,
  `image_caption` varchar(255) DEFAULT NULL,
  `word_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `outbound_links_count` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `outbound_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`outbound_links`)),
  `status` enum('draft','pending_review','published','rejected') NOT NULL DEFAULT 'pending_review',
  `rejection_reason` text DEFAULT NULL,
  `views_count` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `published_at` timestamp NULL DEFAULT NULL,
  `reviewed_by` bigint(20) UNSIGNED DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

